(function() {
    'use strict';

    class CicloAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Ciclo';
            this.version = '1.1.0';
            this.ROUNDS = [
                { panel: 'round1Controls' },
                { panel: 'round2Controls' },
                { panel: 'round3Controls' },
                { panel: 'round4Controls' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 12800000,
                    debt: 55000000,
                    revenue: 285000000,
                    ebitdaMargin: 18,
                    employees: 142,
                    capacityUsed: 76,
                    interestRate: 12.0,
                    steelPrice: 598,
                    steelHedgedTons: 40,
                    steelHedgedPrice: 520,
                    diagnosticScore: 0,
                    strategyChosen: '',
                    cashHistory: [],
                    debtHistory: [],
                    ebitdaHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    cyclePhase: 'recession_early',
                    keyIndicator: 'construction_orders',
                    planningHorizon: '12months',
                    strategy: 'B',
                    recessionProb: 50,
                    priceAdjust: 3,
                    debtAction: 'hold',
                    steelForwardTons: 80,
                    wcPolicy: 'maintain',
                    contingencyThreshold: 15,
                    monitorMetric: 'construction_orders'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;

            if (period === 1) {
                var phase = document.getElementById('cyclePhaseInput');
                if (phase) decisions.cyclePhase = phase.value;
                var indicator = document.getElementById('keyIndicatorInput');
                if (indicator) decisions.keyIndicator = indicator.value;
                var horizon = document.getElementById('planningHorizonInput');
                if (horizon) decisions.planningHorizon = horizon.value;
            } else if (period === 2) {
                var strat = document.getElementById('strategyInput');
                if (strat) decisions.strategy = strat.value;
                var prob = document.getElementById('recessionProbInput');
                if (prob) decisions.recessionProb = parseInt(prob.value);
                var price = document.getElementById('priceAdjustInput');
                if (price) decisions.priceAdjust = parseFloat(price.value);

                if (isNaN(decisions.recessionProb) || decisions.recessionProb < 0 || decisions.recessionProb > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('prob_warning'), 'warning'
                    );
                    return false;
                }
                if (isNaN(decisions.priceAdjust) || decisions.priceAdjust < -10 || decisions.priceAdjust > 15) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('price_adj_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var debt = document.getElementById('debtActionInput');
                if (debt) decisions.debtAction = debt.value;
                var steel = document.getElementById('steelForwardInput');
                if (steel) decisions.steelForwardTons = parseInt(steel.value);
                var wc = document.getElementById('wcPolicyInput');
                if (wc) decisions.wcPolicy = wc.value;

                if (isNaN(decisions.steelForwardTons) || decisions.steelForwardTons < 0 || decisions.steelForwardTons > 180) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('steel_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var threshold = document.getElementById('contingencyThresholdInput');
                if (threshold) decisions.contingencyThreshold = parseInt(threshold.value);
                var monitor = document.getElementById('monitorMetricInput');
                if (monitor) decisions.monitorMetric = monitor.value;

                if (isNaN(decisions.contingencyThreshold) || decisions.contingencyThreshold < 5 || decisions.contingencyThreshold > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('threshold_warning'), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundScore = 0;
            var results = { period: period };

            if (period === 1) {
                var phaseScore = 0;
                if (d.cyclePhase === 'recession_early') phaseScore = 40;
                else if (d.cyclePhase === 'stagnation_risk') phaseScore = 25;
                else if (d.cyclePhase === 'recovery_inflation') phaseScore = 10;

                var indicatorScore = 0;
                if (d.keyIndicator === 'construction_orders') indicatorScore = 35;
                else if (d.keyIndicator === 'unemployment') indicatorScore = 20;
                else if (d.keyIndicator === 'gdp_growth') indicatorScore = 15;
                else if (d.keyIndicator === 'inflation') indicatorScore = 10;

                var horizonScore = 0;
                if (d.planningHorizon === '12months') horizonScore = 25;
                else if (d.planningHorizon === '6months') horizonScore = 15;
                else if (d.planningHorizon === '24months') horizonScore = 10;

                roundScore = phaseScore + indicatorScore + horizonScore;
                ds.diagnosticScore = roundScore;

                results.phaseChosen = d.cyclePhase;
                results.indicatorChosen = d.keyIndicator;
                results.horizonChosen = d.planningHorizon;
                results.diagnosticScore = roundScore;

            } else if (period === 2) {
                var strategyScore = 0;
                var cashImpact = 0;
                var debtImpact = 0;
                var revenueImpact = 0;
                var employeeImpact = 0;

                if (d.strategy === 'A') {
                    cashImpact = -12800000;
                    debtImpact = 15200000;
                    revenueImpact = Math.round(ds.revenue * 0.12);
                    ds.capacityUsed = 95;
                    if (d.recessionProb >= 50) strategyScore = 20;
                    else strategyScore = 45;
                } else if (d.strategy === 'B') {
                    cashImpact = -3200000;
                    debtImpact = 0;
                    revenueImpact = Math.round(ds.revenue * (d.priceAdjust / 100));
                    strategyScore = 55;
                    if (d.recessionProb >= 40 && d.recessionProb <= 70) strategyScore = 65;
                } else if (d.strategy === 'C') {
                    cashImpact = 4600000;
                    debtImpact = -4600000;
                    employeeImpact = -18;
                    revenueImpact = -Math.round(ds.revenue * 0.05);
                    ds.capacityUsed = 62;
                    if (d.recessionProb >= 60) strategyScore = 50;
                    else strategyScore = 30;
                }

                if (d.priceAdjust >= 3 && d.priceAdjust <= 6) strategyScore += 10;

                roundScore = strategyScore;
                ds.cash += cashImpact;
                if (ds.cash < 0) ds.cash = 0;
                ds.debt += debtImpact;
                if (ds.debt < 0) ds.debt = 0;
                ds.revenue += revenueImpact;
                ds.employees += employeeImpact;
                ds.strategyChosen = d.strategy;

                results.strategy = d.strategy;
                results.recessionProb = d.recessionProb;
                results.cashImpact = cashImpact;
                results.debtImpact = debtImpact;
                results.revenueChange = revenueImpact;
                results.newCash = ds.cash;
                results.newDebt = ds.debt;
                results.strategyScore = roundScore;

            } else if (period === 3) {
                var cashChange = 0;
                var debtChange = 0;

                if (d.debtAction === 'pay') {
                    var payment = Math.min(Math.round(ds.cash * 0.4), Math.round(ds.debt * 0.1));
                    cashChange -= payment;
                    debtChange -= payment;
                    roundScore += 25;
                } else if (d.debtAction === 'borrow') {
                    debtChange += 10000000;
                    cashChange += 10000000;
                    ds.interestRate += 1.5;
                    roundScore += 5;
                } else {
                    roundScore += 15;
                }

                var hedgedTons = d.steelForwardTons;
                if (hedgedTons >= 60 && hedgedTons <= 120) {
                    roundScore += 30;
                } else if (hedgedTons > 0) {
                    roundScore += 15;
                } else {
                    roundScore += 5;
                }
                ds.steelHedgedTons += hedgedTons;

                if (d.wcPolicy === 'tighten') {
                    cashChange += 2400000;
                    roundScore += 20;
                } else if (d.wcPolicy === 'loosen') {
                    cashChange -= 1800000;
                    roundScore += 5;
                } else {
                    roundScore += 12;
                }

                ds.interestRate += 0.5;
                var quarterlyInterest = Math.round((ds.debt * (ds.interestRate / 100)) / 4);
                cashChange -= quarterlyInterest;

                ds.cash += cashChange;
                if (ds.cash < 0) ds.cash = 0;
                ds.debt += debtChange;
                if (ds.debt < 0) ds.debt = 0;

                results.debtAction = d.debtAction;
                results.steelForward = hedgedTons;
                results.wcPolicy = d.wcPolicy;
                results.cashChange = cashChange;
                results.interestCost = quarterlyInterest;
                results.newCash = ds.cash;
                results.newDebt = ds.debt;
                results.cashMgmtScore = roundScore;

            } else if (period === 4) {
                var contingencyScore = 0;

                if (d.contingencyThreshold >= 10 && d.contingencyThreshold <= 20) {
                    contingencyScore += 35;
                } else if (d.contingencyThreshold >= 5 && d.contingencyThreshold <= 25) {
                    contingencyScore += 20;
                } else {
                    contingencyScore += 10;
                }

                if (d.monitorMetric === 'construction_orders') contingencyScore += 35;
                else if (d.monitorMetric === 'new_orders') contingencyScore += 25;
                else if (d.monitorMetric === 'unemployment') contingencyScore += 20;
                else contingencyScore += 10;

                if (ds.diagnosticScore >= 60) contingencyScore += 15;
                if (ds.cash > 5000000) contingencyScore += 15;

                roundScore = contingencyScore;

                var annualInterest = ds.debt * (ds.interestRate / 100);
                var projectedEbitda = ds.revenue * (ds.ebitdaMargin / 100);
                var debtServiceRatio = (projectedEbitda > 0) ? (annualInterest / projectedEbitda * 100) : 999;

                results.contingencyThreshold = d.contingencyThreshold;
                results.monitorMetric = d.monitorMetric;
                results.executiveScore = roundScore;
                results.finalCash = ds.cash;
                results.finalDebt = ds.debt;
                results.debtServiceRatio = Math.round(debtServiceRatio * 10) / 10;
                results.projectedEbitda = projectedEbitda;
            }

            ds.cashHistory.push(ds.cash);
            ds.debtHistory.push(ds.debt);
            ds.ebitdaHistory.push(Math.round(ds.revenue * (ds.ebitdaMargin / 100)));
            ds.scoreHistory.push(roundScore);

            // --- Persist a 0-100 overall score for the grading/reporting layer ---
            // Contract: the DB grade + reports resolve domainState.performance.overallScore, then domainState.score.
            // Use the sim's own decision-quality metric: the running average of per-round scores (already the
            // "Decision Quality Score" charted here, and the avgScore returned by getPerformanceSummary). 0-100 by construction.
            var _avg = Math.round(ds.scoreHistory.reduce(function(s, r) { return s + r; }, 0) / ds.scoreHistory.length);
            var overallScore = Math.max(0, Math.min(100, _avg));
            var perfGrade = 'Needs Improvement';
            if (overallScore >= 70) perfGrade = 'Excellent';
            else if (overallScore >= 50) perfGrade = 'Good';
            ds.score = overallScore;
            ds.performance = { overallScore: overallScore, grade: perfGrade };

            results.overallScore = overallScore;
            results.score = overallScore;
            results.roundScore = roundScore;
            results.cash = ds.cash;
            results.debt = ds.debt;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return 'HNL ' + Math.round(v / 1000000).toLocaleString() + 'M'; });
            uiManager.bind('debtDisplay', 'domainState.debt',
                function(v) { return 'HNL ' + Math.round(v / 1000000).toLocaleString() + 'M'; });
            uiManager.bind('revenueDisplay', 'domainState.revenue',
                function(v) { return 'HNL ' + Math.round(v / 1000000).toLocaleString() + 'M'; });
            uiManager.bind('employeesDisplay', 'domainState.employees');
            uiManager.bind('capacityDisplay', 'domainState.capacityUsed',
                function(v) { return v + '%'; });
            uiManager.bind('rateDisplay', 'domainState.interestRate',
                function(v) { return v.toFixed(1) + '%'; });
        }

        getChartConfig() {
            return {
                financialChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Cash (HNL M)',
                            data: [],
                            backgroundColor: 'rgba(69, 183, 132, 0.65)',
                            borderColor: '#45b784',
                            borderWidth: 2
                        }, {
                            label: 'Debt (HNL M)',
                            data: [],
                            backgroundColor: 'rgba(232, 84, 84, 0.65)',
                            borderColor: '#e85454',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cash vs Debt Position', color: '#c8cdd8', font: { size: 13 } },
                            legend: { labels: { color: '#7a8299', font: { size: 11 } } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#7a8299' }, grid: { color: 'rgba(122,130,153,0.12)' } },
                            x: { ticks: { color: '#7a8299' }, grid: { color: 'rgba(122,130,153,0.12)' } }
                        }
                    }
                },
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            borderColor: '#4a90d9',
                            backgroundColor: 'rgba(74, 144, 217, 0.12)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            pointBackgroundColor: '#4a90d9',
                            pointRadius: 5,
                            pointHoverRadius: 7
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Decision Quality Score', color: '#c8cdd8', font: { size: 13 } },
                            legend: { labels: { color: '#7a8299', font: { size: 11 } } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#7a8299' }, grid: { color: 'rgba(122,130,153,0.12)' } },
                            x: { ticks: { color: '#7a8299' }, grid: { color: 'rgba(122,130,153,0.12)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.cashHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.cashHistory.map(function(v) { return Math.round(v / 1000000); }) },
                        { data: state.domainState.debtHistory.map(function(v) { return Math.round(v / 1000000); }) }
                    ]
                },
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? (r.results.roundScore || 0) : 0; });
            var totalScore = scores.reduce(function(s, p) { return s + p; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var lastRecord = history[history.length - 1];
            var finalCash = lastRecord.results ? (lastRecord.results.cash || 0) : 0;
            var finalDebt = lastRecord.results ? (lastRecord.results.debt || 0) : 0;

            var performance = 'Needs Improvement';
            if (totalScore > 200 && finalCash > 5000000) performance = 'Good';
            if (totalScore > 280 && finalCash > 8000000) performance = 'Excellent';

            var insights = [];
            if (avgScore >= 70) insights.push('Strong analytical approach to economic cycle management.');
            else if (avgScore >= 45) insights.push('Reasonable decisions but room for deeper scenario analysis.');
            else insights.push('Review how leading indicators predict cycle turns for your industry.');

            if (finalDebt > 60000000) insights.push('High debt levels increase vulnerability to rate hikes during downturns.');
            if (finalCash < 5000000) insights.push('Low cash reserves limit flexibility during a recession.');

            return {
                overallScore: avgScore,
                score: avgScore,
                totalScore: totalScore,
                avgScore: avgScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.diagnosticScore !== undefined && results.diagnosticScore < 50) {
                return window.mySimulation.t('hint_diagnostic');
            }
            if (period === 2 && results.strategy === 'A' && results.recessionProb > 50) {
                return window.mySimulation.t('hint_aggressive_risk');
            }
            if (period === 3 && results.newCash !== undefined && results.newCash < 3000000) {
                return window.mySimulation.t('hint_low_cash');
            }
            if (period === 4 && results.debtServiceRatio !== undefined && results.debtServiceRatio > 16) {
                return window.mySimulation.t('hint_debt_ratio');
            }
            return null;
        }

